from __future__ import annotations

import json
import logging
import pathlib
import shutil
from contextlib import contextmanager
from inspect import stack
from typing import Generator

import docker
import requests

from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import SERVER_HOST
from ta_logcollector.utils.emil import repeat
from ta_logcollector.utils.enums import RAT

class EmilContainerNotFound(Exception):
    pass

DOCKER_START_TIMEOUT = 120
EMIL_REQUEST_HEADERS = {
    "accept": "application/json",
    "accept-encoding": "gzip, deflate, br",
    "authorization": "Bearer BIG_PASSWORD_HERE",
    "user-agent": "node-fetch",
}
SACKSERVICE_CONTAINER_NAME = "ondemand_emil_sackservice"
EMIL_DATA_COLLECTION_PROFILE_NAME = {RAT.LTE: "AaTrace", RAT.NR: "CPlane_Traces_5G"}
EMIL_CONTAINER_LOG_PATH = pathlib.Path("/sharedvolume/condor/logcollector")

logger = logging.Logger("LC")

def stop_docker_container(
    docker_client: docker.DockerClient, container_name: str
) -> None:
    try:
        docker_client.api.stop(container_name)
        logger.debug(f"'Docker container {container_name} stopped")
    except Exception as err:
        logger.debug(f"Error while stopping docker container: {err}")
        raise RuntimeError(
            f"Cannot stop docker container '{container_name}'. Error: {err}"
        ) from err


def start_container(
    docker_client: docker.DockerClient, container_name: str, logger: logging.Logger
) -> None:
    if check_container_health(docker_client, container_name)[0]:
        return
    try:
        docker_client.api.start(container_name)
        logger.debug(f"'Docker container '{container_name}' started")
    except Exception as err:
        logger.debug(f"Error while starting docker container: {err}")
        raise RuntimeError(
            f"Cannot start docker container '{container_name}'. Error: {err}"
        ) from err


def check_container_health(
    docker_client: docker.DockerClient, container_name: str
) -> tuple[bool, bool, str]:
    state = docker_client.containers.get(container_name).attrs["State"]
    status = state["Status"].lower()
    running = state["Running"]
    healthy = state["Health"]["Status"].lower() if "Health" in state else "healthy"
    msg = f"Docker startup status: {status = }, {running = }, {healthy = }"
    if all((status == "running", running is True, healthy == "healthy")):
        return True, True, msg
    return False, False, msg


def _get_start_request_template(
    rat: RAT, ip_address: str, msgs: str, heavy_load_msgs: str
) -> dict[str, str]:
    return {
        "dataCollectionProfileId": EMIL_DATA_COLLECTION_PROFILE_NAME[rat],
        "trackingTag": "logcollector",
        "ownerEmail": "dummy.email@nokia.com",
        "targetElement": {"ipAddress": ip_address, "name": ip_address},
        "dataCollectionParameters": [
            {"name": "newTc", "values": ["false" if rat == RAT.LTE else "true"]},
            {"name": "duration", "values": ["2147483647"]},
            {"name": "admin_user", "values": ["Nemuadmin"]},
            {"name": "admin_password", "values": ["nemuuser"]},
            {"name": "adminPort", "values": ["443"]},
            {"name": "checkRnDPorts", "values": ["false"]},
        ],
        "MonitorProfileParameters": [
            {
                "rat": rat.name,
                "syscomMessageFilter": msgs,
                "heavyLoadMessages": heavy_load_msgs,
                "zmqSctpComponents": "*",
            }
        ],
    }

def start_collecting_emil_logs(msgs: str, heavy_load: str, rat: RAT, bts_ip: str, emil_container_ip: str):
    request_data = _get_start_request_template(rat, bts_ip, msgs, heavy_load)
    logger.debug(f"Request data: {request_data}")
    req_files = {"dataCollectionSpec": (None, json.dumps(request_data))}
    emil_container_url = get_container_url(emil_container_ip)

    def _send_start_request(files: dict) -> tuple[bool, bool, str]:
        r = requests.post(emil_container_url, files=files, headers=EMIL_REQUEST_HEADERS)
        if r.status_code == 200:
            return True, True, r.json()
        return False, False, f"Something has gone wrong. {r.text}"

    repeat(_send_start_request, req_files, timeout=20, logger=logger)


def stop_collecting_emil_logs(rat: RAT, bts_ip: str, emil_container_ip: str):
    emil_container_url = get_container_url(emil_container_ip)

    def _send_stop_logs_collecting():
        dc_full_name = _get_data_collection_full_name(bts_ip, rat, emil_container_ip)
        r = requests.delete(
            f"{emil_container_url}/{dc_full_name}", headers=EMIL_REQUEST_HEADERS
        )
        if r.status_code == 200:
            return True, True, r.json()
        return False, False, f"Something has gone wrong. {r.text}"

    repeat(_send_stop_logs_collecting, timeout=10, logger=logger)


def is_emil_collecting_started(rat: RAT, bts_ip: str, emil_container_ip: str):
    dc_full_name = _get_data_collection_full_name(bts_ip, rat, emil_container_ip)
    emil_container_url = get_container_url(emil_container_ip)
    r = requests.get(
        f"{emil_container_url}/{dc_full_name}", headers=EMIL_REQUEST_HEADERS
    )
    try:
        if (resp_json := r.json())["targetStatus"]["connection_phase"] == 2:
            return True, True, resp_json
    except Exception as err:
        logger.debug(err)
    return False, False, r.text


def _get_data_collection_full_name(bts_ip: str, rat: RAT, emil_container_ip: str):
    return f"{EMIL_DATA_COLLECTION_PROFILE_NAME[rat]}-{bts_ip}-{emil_container_ip}"

def check_container_start(docker_client, container_name, logger):
    try:
        container = docker_client.containers.get(container_name)
        if container.status != 'running':
            start_container(docker_client, container_name, logger)
        else:
            logger.debug(f"Docker container {container_name} is already running")
    except docker.errors.NotFound:
        logger.debug(f"Docker container {container_name} not found")


def start(
    docker_client: docker.DockerClient,
    msgs: str,
    heavy_load: str,
    rat: RAT,
    bts_ip: str
) -> None:
    start_container(docker_client, SACKSERVICE_CONTAINER_NAME, logger)
    container_name = get_container_name(docker_client, rat)
    check_container_start(docker_client, container_name, logger)
    if not repeat(
        check_container_health,
        docker_client,
        container_name,
        timeout=DOCKER_START_TIMEOUT,
        logger=logger,
    ):
        raise RuntimeError(
            "Docker for emil did not start in 120s. Cannot collect emil logs."
        )

    emil_container_ip = get_container_ip(docker_client, container_name, logger)
    start_collecting_emil_logs(msgs, heavy_load, rat, bts_ip, emil_container_ip)
    if not repeat(is_emil_collecting_started, rat, bts_ip, emil_container_ip, timeout=60, logger=logger):
        raise RuntimeError("Couldn't start emil log collection in time.")


def move_logs(log_dir: pathlib.Path):
    logger.debug(f"Copying logs from '{EMIL_CONTAINER_LOG_PATH}' to '{log_dir}'")
    assert EMIL_CONTAINER_LOG_PATH.exists()
    log_dir.mkdir(parents=True, exist_ok=True)
    shutil.copytree(EMIL_CONTAINER_LOG_PATH, f"{log_dir}/emil")
    logger.info(f"Logs copied to '{log_dir}'")
    rmdir(EMIL_CONTAINER_LOG_PATH)
    logger.info(f"'{EMIL_CONTAINER_LOG_PATH}' removed.")


def rmdir(directory):
    dirs = []
    for item in directory.iterdir():
        if item.is_dir():
            rmdir(item)
            dirs.append(item)
        else:
            item.unlink()
    for _dir in dirs:
        _dir.rmdir()


def stop(
    docker_client: docker.DockerClient,
    log_dir: pathlib.Path,
    rat: RAT,
    bts_ip: str,
    stop_docker: bool,
):

    emil_container_ip = get_container_ip(docker_client, get_container_name(docker_client, rat), logger)
    stop_collecting_emil_logs(rat, bts_ip, emil_container_ip)
    if stop_docker:
        stop_docker_container(docker_client, get_container_name(docker_client, rat))
    move_logs(log_dir)

def get_container_ip(client, container_name, logger):
    try:
        container = client.containers.get(container_name)
        container_info = container.attrs
        ip_address = container_info['NetworkSettings']['Networks']['utf_lab_net']['IPAMConfig']['IPv4Address']
        return ip_address
    except docker.errors.NotFound:
        logger.debug("Cannot find container")
        return None

def get_best_match_container(container_names, rat: RAT):
    is_5g = True if rat == RAT.NR else False
    match_container = [container for container in container_names if "5g" in container and is_5g]
    return match_container[0] if len(match_container) > 0 else container_names[0]

def get_container_name(client, rat: RAT):
    containers = client.containers.list(all=True)
    container_names = [container.name for container in containers if "ondemand_emil_datacollector" in container.name]
    if len(container_names) == 0:
        logger.debug("Container ondemand_emil_datacollector not found")
        raise EmilContainerNotFound("Emil container ondemand_emil_datacollector not found")
    return get_best_match_container(container_names, rat)


def get_container_url(emil_container_ip: str):
    return f"http://{emil_container_ip}:10009/dataCollections"

@contextmanager
def emil(
    log_host: str,
    log_port: int,
    msgs: str,
    heavy_load: str,
    rat: RAT,
    stop_docker: bool,
    bts_ip: str,
    **kwargs,
) -> Generator[None, None, None]:
    """
    Plugin to gather trace logs for EMIL tool. It uses configuration specified in /home/ute/btslog2/
    :param str log_host: IP address of logger host
    :param int log_port: port of logger host
    :param str msgs: list of messages IDs to be collected
    :param str heavy_load: list of heavy load messages IDs to be collected
    :param :class:`RAT` rat: name of RadioAccessTechnology which is supposed to be used. Either LTE or NR.
    :param bool stop_docker: Information if upon stop action, docker container should also be stopped or not.
    :param str bts_ip: IP address of BTS
    """
    global logger
    logger = get_net_logger(
        log_host, log_port, "{}_{}".format(stack(0)[0][3], SERVER_HOST)
    )

    log_dir = pathlib.Path(kwargs.pop("log_dir"))
    docker_client = docker.from_env()
    assert rat in RAT, "Unknown RAT value."

    try:
        start(docker_client, msgs, heavy_load, rat, bts_ip)
        yield
    finally:
        stop(docker_client, log_dir, rat, bts_ip, stop_docker)
